1	//! Standalone, executable acceptance target for the production builder path
2	//! of a layered plugin-dispatch CLI.
3	//!
4	//! This file never touches the derive facade: the command graph is built with
5	//! the public `clap::Command`/`Arg` builder and every result is observed
6	//! solely through the public production entry point
7	//! [`clap::Command::try_get_matches_from`] with argv0 included (`tool`, ...).
8	//! Nothing is read through test-only internals: success state comes from the
9	//! returned `ArgMatches`, failures from the public `clap::Error` (kind plus
10	//! rendered text) and help from the `DisplayHelp` error.
11	//!
12	//! Scenario under test:
13	//! * root command `tool` with a global `--config <path>` defaulting to
14	//!   `builtin.toml`, and a root-level repeatable `--define key=value` that
15	//!   accepts only exactly one non-empty key, one non-empty value and exactly
16	//!   one `=` separator, with no whitespace on either side of the pair;
17	//! * declared subcommands `serve` and `check`, plus a root external
18	//!   catch-all; `serve` declares `worker` and has its own external catch-all;
19	//! * `--define` is root-scoped rather than global: it parses only while the
20	//!   root command is active, keeps occurrence order, is rejected with the
21	//!   triggering token at any deeper level, and is never parsed once either
22	//!   external capture starts;
23	//! * `worker` requires exactly one `--port` built only from ASCII decimal
24	//!   digits in 1..=65535: empty strings, sign prefixes, hex, underscores,
25	//!   embedded whitespace and overflowing values are reported instead of being
26	//!   normalized, truncated or accepted;
27	//! * `--http` and `--https` are mutually exclusive; tokens after worker's own
28	//!   standalone `--` are trailing verbatim data in order, and without the
29	//!   separator a bare token is an unknown argument rather than trailing data;
30	//! * `check` takes only an optional path and `--strict` and never accepts
31	//!   worker-owned arguments;
32	//! * the global config parses before or after at any level while defines keep
33	//!   occurrence order at theirs, and once an external command name is fixed
34	//!   every following token belongs to that plugin verbatim;
35	//! * validation failures keep the distinguishable public error kinds for
36	//!   missing arguments, missing/invalid values, conflicts and unknown tokens,
37	//!   name the most specific command and the triggering token, and never leave
38	//!   a partial match readable;
39	//! * help for root, serve, worker and check succeeds even while required
40	//!   values are missing, shows only that level's surface, defaults,
41	//!   subcommands and external-capture boundary, and carries no stale error;
42	//! * a fixed sequence of external success, every invalid-define class, port
43	//!   failures, a valid worker after the failures and help requests is mutually
44	//!   isolated, and moving the global arguments around changes neither the
45	//!   success data, define order, trailing order, error usage nor help order.
46	#![cfg(feature = "help")]
47	#![cfg(feature = "usage")]
48	
49	use clap::Arg;
50	use clap::ArgAction;
51	use clap::ArgMatches;
52	use clap::Command;
53	use clap::error::ErrorKind;
54	use clap::value_parser;
55	
56	/// Strict `key=value` parser for root-level definitions.
57	///
58	/// Exactly one `=` separator, a non-empty key, a non-empty value and no
59	/// whitespace on either side of the pair. Empty keys, empty values, leading
60	/// or trailing `=`, additional `=` and whitespace around the pair are all
61	/// rejected instead of being trimmed, split further or silently accepted.
62	fn parse_define(raw: &str) -> Result<(String, String), String> {
63	    let Some((key, value)) = raw.split_once('=') else {
64	        return Err(format!("invalid define `{raw}`: expected key=value"));
65	    };
66	    if value.contains('=') {
67	        return Err(format!(
68	            "invalid define `{raw}`: expected exactly one `=` in key=value"
69	        ));
70	    }
71	    if key.is_empty() {
72	        return Err(format!("invalid define `{raw}`: key must not be empty"));
73	    }
74	    if value.is_empty() {
75	        return Err(format!("invalid define `{raw}`: value must not be empty"));
76	    }
77	    if key.chars().any(char::is_whitespace) || value.chars().any(char::is_whitespace) {
78	        return Err(format!(
79	            "invalid define `{raw}`: key and value must not contain whitespace"
80	        ));
81	    }
82	    Ok((key.to_owned(), value.to_owned()))
83	}
84	
85	/// Strict decimal port parser: ASCII digits only, range 1..=65535.
86	///
87	/// Signs, hex prefixes, underscores, whitespace and empty values are all
88	/// rejected instead of being normalized, truncated or wrapped by a lenient
89	/// integer conversion.
90	fn parse_port(raw: &str) -> Result<u16, String> {
91	    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
92	        return Err(format!(
93	            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
94	        ));
95	    }
96	    match raw.parse::<u32>() {
97	        Ok(port) if (1..=65535).contains(&port) => Ok(port as u16),
98	        _ => Err(format!(
99	            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
100	        )),
101	    }
102	}
103	
104	/// The production command graph, constructed through the public builder only.
105	///
106	/// A fresh `Command` is built for every parse: the builder is consumed by
107	/// `try_get_matches_from`, and rebuilding here also proves that one parse's
108	/// state can never leak into the next.
109	fn tool() -> Command {
110	    Command::new("tool")
111	        .after_help("External plugins: any other <COMMAND> is captured as a root plugin.")
112	        .arg(
113	            Arg::new("config")
114	                .long("config")
115	                .global(true)
116	                .default_value("builtin.toml")
117	                .value_name("path"),
118	        )
119	        .arg(
120	            Arg::new("define")
121	                .long("define")
122	                .value_name("key=value")
123	                .action(ArgAction::Append)
124	                .value_parser(parse_define),
125	        )
126	        .subcommand_required(true)
127	        .arg_required_else_help(true)
128	        .allow_external_subcommands(true)
129	        .external_subcommand_value_parser(value_parser!(String))
130	        .subcommand(
131	            Command::new("serve")
132	                .after_help("External plugins: any other <COMMAND> is captured as a serve plugin.")
133	                .subcommand_required(true)
134	                .arg_required_else_help(true)
135	                .allow_external_subcommands(true)
136	                .external_subcommand_value_parser(value_parser!(String))
137	                .subcommand(
138	                    Command::new("worker")
139	                        .arg(
140	                            Arg::new("port")
141	                                .long("port")
142	                                .value_name("port")
143	                                .required(true)
144	                                .value_parser(parse_port),
145	                        )
146	                        .arg(
147	                            Arg::new("http")
148	                                .long("http")
149	                                .action(ArgAction::SetTrue)
150	                                .conflicts_with("https"),
151	                        )
152	                        .arg(
153	                            Arg::new("https")
154	                                .long("https")
155	                                .action(ArgAction::SetTrue)
156	                                .conflicts_with("http"),
157	                        )
158	                        // Positional `Vec` slot, mirrored from the derive
159	                        // shape: Append + `num_args(1..)` + `last`, so the
160	                        // slot is reachable only through the standalone `--`
161	                        // and then consumes every remaining token verbatim.
162	                        .arg(
163	                            Arg::new("trailing")
164	                                .value_name("TRAILING")
165	                                .action(ArgAction::Append)
166	                                .num_args(1..)
167	                                .last(true),
168	                        ),
169	                ),
170	        )
171	        .subcommand(
172	            Command::new("check")
173	                .arg(Arg::new("path").value_name("PATH").action(ArgAction::Set))
174	                .arg(Arg::new("strict").long("strict").action(ArgAction::SetTrue)),
175	        )
176	}
177	
178	fn parse(argv: &[&str]) -> Result<ArgMatches, clap::Error> {
179	    tool().try_get_matches_from(argv)
180	}
181	
182	/// Success state observed on the `tool serve worker` path.
183	#[derive(Debug, Clone, PartialEq, Eq)]
184	struct WorkerState {
185	    config: String,
186	    define: Vec<(String, String)>,
187	    port: u16,
188	    http: bool,
189	    https: bool,
190	    trailing: Vec<String>,
191	}
192	
193	/// Success state observed on the `tool check` path.
194	#[derive(Debug, Clone, PartialEq, Eq)]
195	struct CheckState {
196	    config: String,
197	    define: Vec<(String, String)>,
198	    path: Option<String>,
199	    strict: bool,
200	}
201	
202	/// Success state observed on either external-capture path. The plugin command
203	/// name is the first token.
204	#[derive(Debug, Clone, PartialEq, Eq)]
205	struct ExternalState {
206	    config: String,
207	    define: Vec<(String, String)>,
208	    tokens: Vec<String>,
209	}
210	
211	fn read_config(matches: &ArgMatches) -> String {
212	    matches
213	        .get_one::<String>("config")
214	        .cloned()
215	        .expect("global --config always carries a value, default or explicit")
216	}
217	
218	fn read_define(matches: &ArgMatches) -> Vec<(String, String)> {
219	    matches
220	        .get_many::<(String, String)>("define")
221	        .map(|values| values.cloned().collect())
222	        .unwrap_or_default()
223	}
224	
225	fn external_tokens(name: &str, ext: &ArgMatches) -> Vec<String> {
226	    let mut tokens = vec![name.to_owned()];
227	    tokens.extend(
228	        ext.get_many::<String>("")
229	            .expect("external capture stores its tokens under the empty id")
230	            .cloned(),
231	    );
232	    tokens
233	}
234	
235	/// An external capture is a subcommand whose own matches hold the captured
236	/// tokens under clap's empty id. That marker -- not the name -- distinguishes
237	/// it from a declared command, because a root-level `--` can force a token that
238	/// looks like a declared name (`serve`, `worker`) to be captured as a plugin.
239	fn is_external(matches: &ArgMatches) -> bool {
240	    matches.get_many::<String>("").is_some()
241	}
242	
243	fn worker_ok(argv: &[&str]) -> WorkerState {
244	    let matches = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
245	    let (root_name, serve_matches) = matches
246	        .subcommand()
247	        .unwrap_or_else(|| panic!("expected a subcommand for {argv:?}, got root matches"));
248	    assert_eq!(root_name, "serve", "{argv:?}");
249	    let (name, worker_matches) = serve_matches
250	        .subcommand()
251	        .unwrap_or_else(|| panic!("expected `serve worker` for {argv:?}"));
252	    assert_eq!(name, "worker", "{argv:?}");
253	    let state = WorkerState {
254	        config: read_config(worker_matches),
255	        define: read_define(&matches),
256	        port: *worker_matches
257	            .get_one::<u16>("port")
258	            .unwrap_or_else(|| panic!("worker port missing for {argv:?}")),
259	        http: worker_matches.get_flag("http"),
260	        https: worker_matches.get_flag("https"),
261	        trailing: worker_matches
262	            .get_many::<String>("trailing")
263	            .map(|values| values.cloned().collect())
264	            .unwrap_or_default(),
265	    };
266	    eprintln!(
267	        "{argv:?} => worker: config={:?} define={:?} port={} http={} https={} trailing={:?}",
268	        state.config, state.define, state.port, state.http, state.https, state.trailing
269	    );
270	    state
271	}
272	
273	fn check_ok(argv: &[&str]) -> CheckState {
274	    let matches = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
275	    let (name, check_matches) = matches
276	        .subcommand()
277	        .unwrap_or_else(|| panic!("expected a subcommand for {argv:?}"));
278	    assert_eq!(name, "check", "{argv:?}");
279	    let state = CheckState {
280	        config: read_config(check_matches),
281	        define: read_define(&matches),
282	        path: check_matches.get_one::<String>("path").cloned(),
283	        strict: check_matches.get_flag("strict"),
284	    };
285	    eprintln!(
286	        "{argv:?} => check: config={:?} define={:?} path={:?} strict={}",
287	        state.config, state.define, state.path, state.strict
288	    );
289	    state
290	}
291	
292	fn root_external_ok(argv: &[&str]) -> ExternalState {
293	    let matches = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
294	    let (name, ext_matches) = matches
295	        .subcommand()
296	        .unwrap_or_else(|| panic!("expected an external subcommand for {argv:?}"));
297	    assert!(
298	        is_external(ext_matches),
299	        "declared command {name} dispatched for {argv:?}"
300	    );
301	    let state = ExternalState {
302	        config: read_config(&matches),
303	        define: read_define(&matches),
304	        tokens: external_tokens(name, ext_matches),
305	    };
306	    assert!(
307	        !state.tokens.is_empty(),
308	        "capture must include the name: {argv:?}"
309	    );
310	    eprintln!(
311	        "{argv:?} => root plugin: config={:?} define={:?} tokens={:?}",
312	        state.config, state.define, state.tokens
313	    );
314	    state
315	}
316	
317	fn serve_external_ok(argv: &[&str]) -> ExternalState {
318	    let matches = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
319	    let (root_name, serve_matches) = matches
320	        .subcommand()
321	        .unwrap_or_else(|| panic!("expected a subcommand for {argv:?}"));
322	    assert_eq!(root_name, "serve", "{argv:?}");
323	    let (name, ext_matches) = serve_matches
324	        .subcommand()
325	        .unwrap_or_else(|| panic!("expected a serve external subcommand for {argv:?}"));
326	    assert!(
327	        is_external(ext_matches),
328	        "declared command {name} dispatched for {argv:?}"
329	    );
330	    let state = ExternalState {
331	        config: read_config(serve_matches),
332	        define: read_define(&matches),
333	        tokens: external_tokens(name, ext_matches),
334	    };
335	    assert!(
336	        !state.tokens.is_empty(),
337	        "capture must include the name: {argv:?}"
338	    );
339	    eprintln!(
340	        "{argv:?} => serve plugin: config={:?} define={:?} tokens={:?}",
341	        state.config, state.define, state.tokens
342	    );
343	    state
344	}
