346	/// Render an error while dropping the optional backtrace appended by clap's
347	/// `debug` feature. The backtrace captures host paths and frame line numbers
348	/// and is not part of the user-facing help or error output under test.
349	fn rendered(err: &clap::Error) -> String {
350	    let text = err.to_string();
351	    match text.split_once("\nBacktrace:") {
352	        Some((head, _)) => head.trim_end().to_owned(),
353	        None => text,
354	    }
355	}
356	
357	fn fail_kind(argv: &[&str]) -> (ErrorKind, String) {
358	    match parse(argv) {
359	        // A failure case that parses would leave a partially populated match
360	        // readable; the acceptance contract forbids that.
361	        Ok(matches) => panic!("expected failure for {argv:?}, got {matches:?}"),
362	        Err(err) => {
363	            let kind = err.kind();
364	            let msg = rendered(&err);
365	            let first_line = msg.lines().next().unwrap_or_default().to_owned();
366	            eprintln!("{argv:?} => error kind={kind:?}: {first_line}");
367	            (kind, msg)
368	        }
369	    }
370	}
371	
372	fn help_text(argv: &[&str]) -> String {
373	    let err = parse(argv).expect_err("help is reported as a DisplayHelp error");
374	    assert_eq!(err.kind(), ErrorKind::DisplayHelp, "{argv:?}");
375	    let help = rendered(&err);
376	    eprintln!("{argv:?} => help ({} bytes)", help.len());
377	    help
378	}
