380	/// Semantic snapshot of a successful parse: only the business values the
381	/// caller can read back. Positional bookkeeping (the index at which an option
382	/// happened to appear) is intentionally excluded, since moving an option
383	/// changes that index without changing any success data.
384	#[derive(Debug, Clone, PartialEq, Eq)]
385	enum Snapshot {
386	    Worker(WorkerState),
387	    Check(CheckState),
388	    RootExternal(ExternalState),
389	    ServeExternal(ExternalState),
390	}
391	
392	fn snapshot(argv: &[&str]) -> Snapshot {
393	    let matches = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
394	    let (name, sub) = matches.subcommand().expect("a subcommand is required");
395	    // Check the external marker first: a root-level `--` can force a plugin
396	    // whose name coincides with a declared command.
397	    if is_external(sub) {
398	        return Snapshot::RootExternal(ExternalState {
399	            config: read_config(&matches),
400	            define: read_define(&matches),
401	            tokens: external_tokens(name, sub),
402	        });
403	    }
404	    match name {
405	        "serve" => {
406	            let (serve_name, serve_sub) = sub.subcommand().expect("serve requires a subcommand");
407	            if is_external(serve_sub) {
408	                Snapshot::ServeExternal(ExternalState {
409	                    config: read_config(sub),
410	                    define: read_define(&matches),
411	                    tokens: external_tokens(serve_name, serve_sub),
412	                })
413	            } else {
414	                assert_eq!(serve_name, "worker", "{argv:?}");
415	                Snapshot::Worker(WorkerState {
416	                    config: read_config(serve_sub),
417	                    define: read_define(&matches),
418	                    port: *serve_sub.get_one::<u16>("port").expect("worker port"),
419	                    http: serve_sub.get_flag("http"),
420	                    https: serve_sub.get_flag("https"),
421	                    trailing: serve_sub
422	                        .get_many::<String>("trailing")
423	                        .map(|values| values.cloned().collect())
424	                        .unwrap_or_default(),
425	                })
426	            }
427	        }
428	        "check" => Snapshot::Check(CheckState {
429	            config: read_config(sub),
430	            define: read_define(&matches),
431	            path: sub.get_one::<String>("path").cloned(),
432	            strict: sub.get_flag("strict"),
433	        }),
434	        other => panic!("unexpected declared subcommand {other} for {argv:?}"),
435	    }
436	}
