438	// ---- dispatch: declared commands take precedence over external capture ----
439	
440	#[test]
441	fn declared_commands_are_not_swallowed_by_external_capture() {
442	    // Declared names dispatch to the built-in commands at both levels.
443	    let matches = parse(&["tool", "check"]).unwrap();
444	    assert_eq!(matches.subcommand().unwrap().0, "check");
445	    let worker = worker_ok(&["tool", "serve", "worker", "--port", "8080"]);
446	    assert_eq!(worker.port, 8080);
447	
448	    // Prefixes and look-alikes stay external.
449	    assert_eq!(
450	        root_external_ok(&["tool", "ser", "x"]).tokens,
451	        vec!["ser", "x"]
452	    );
453	    assert_eq!(
454	        serve_external_ok(&["tool", "serve", "work", "x"]).tokens,
455	        vec!["work", "x"]
456	    );
457	    // `check` is declared at the root only, so under `serve` it is a plugin.
458	    assert_eq!(
459	        serve_external_ok(&["tool", "serve", "check"]).tokens,
460	        vec!["check"]
461	    );
462	
463	    // A bare `worker` at the root is a root plugin, never the nested command.
464	    let ext = root_external_ok(&["tool", "worker", "--port", "8080"]);
465	    assert_eq!(ext.tokens, vec!["worker", "--port", "8080"]);
466	}
