468	#[test]
469	fn missing_subcommand_shows_that_levels_help_without_dispatching() {
470	    let (kind, _) = fail_kind(&["tool"]);
471	    assert_eq!(kind, ErrorKind::DisplayHelpOnMissingArgumentOrSubcommand);
472	    let (kind, msg) = fail_kind(&["tool", "serve"]);
473	    assert_eq!(kind, ErrorKind::DisplayHelpOnMissingArgumentOrSubcommand);
474	    assert!(msg.contains("tool serve"), "{msg}");
475	    assert!(msg.contains("worker"), "{msg}");
476	}
