480	#[test]
481	fn defines_keep_occurrence_order_and_split_into_pairs() {
482	    let state = worker_ok(&[
483	        "tool",
484	        "--define",
485	        "a=1",
486	        "--define",
487	        "b=two",
488	        "--define=c=3",
489	        "--config",
490	        "custom.toml",
491	        "serve",
492	        "worker",
493	        "--port",
