508	#[test]
509	fn define_pairs_keep_inner_punctuation_verbatim() {
510	    // Punctuation that is neither `=` nor whitespace is part of the data and
511	    // is never trimmed or reinterpreted.
512	    let state = worker_ok(&[
513	        "tool",
514	        "--define",
515	        "a.b-c_d=e/f:1",
516	        "--define",
517	        "x=y,z;w",
518	        "--define",
519	        "1=2",
520	        "serve",
521	        "worker",
522	        "--port",
523	        "80",
524	    ]);
525	    assert_eq!(
526	        state.define,
527	        vec![
528	            ("a.b-c_d".to_owned(), "e/f:1".to_owned()),
529	            ("x".to_owned(), "y,z;w".to_owned()),
530	            ("1".to_owned(), "2".to_owned()),
531	        ]
532	    );
533	}
