535	#[test]
536	fn defines_parse_only_until_any_external_capture_starts() {
537	    // Root capture: defines before the name parse, everything after is data.
538	    let ext = root_external_ok(&["tool", "--define", "k=v", "plug", "--define", "x=y"]);
539	    assert_eq!(ext.define, vec![("k".to_owned(), "v".to_owned())]);
540	    assert_eq!(ext.tokens, vec!["plug", "--define", "x=y"]);
541	
542	    // Serve capture: a define between `serve` and the plugin name is a
543	    // serve-level token and is covered by the wrong-level failures; once the
544	    // serve plugin name is selected, define-like tokens are plugin data.
545	    let ext = serve_external_ok(&[
546	        "tool", "--define", "k=v", "serve", "plug", "--define", "x=y",
547	    ]);
548	    assert_eq!(ext.define, vec![("k".to_owned(), "v".to_owned())]);
549	    assert_eq!(ext.tokens, vec!["plug", "--define", "x=y"]);
550	}
