552	// ---- invalid defines: one case per rejected class -------------------------
553	
554	/// Every class of malformed definition, with the exact token under test.
555	const INVALID_DEFINES: &[&str] = &[
556	    "",        // empty string
557	    "=",       // only a separator: empty key and empty value
558	    "=v",      // leading equals: empty key
559	    "k=",      // trailing equals: empty value
560	    "a=b=c",   // more than one separator
561	    "novalue", // no separator at all
562	    " a=b",    // whitespace before the key
563	    "a =b",    // whitespace after the key
564	    "a= b",    // whitespace before the value
565	    "a=b ",    // whitespace after the value
566	    "a b=c",   // whitespace inside the key
567	    "a=b c",   // whitespace inside the value
568	];
569	
570	#[test]
571	fn every_invalid_define_class_is_a_value_validation_error() {
572	    for raw in INVALID_DEFINES {
573	        for argv in [
574	            vec!["tool", "--define", raw, "serve", "worker", "--port", "80"],
575	            vec![
