674	fn every_non_decimal_or_out_of_range_port_is_an_invalid_value() {
675	    // Attached form: every token reaches the port parser as its value.
676	    for bad in [
677	        "",                     // empty string
678	        "-1",                   // negative sign prefix
679	        "+80",                  // plus sign prefix
680	        "0x10",                 // hexadecimal
681	        "1_000",                // digit separator
682	        " 80",                  // leading whitespace
683	        "80 ",                  // trailing whitespace
684	        "8 0",                  // embedded whitespace
685	        "abc",                  // non-numeric
686	        "0",                    // below the range
687	        "65536",                // above the range
688	        "99999999999999999999", // overflows any machine integer
689	    ] {
690	        let argv = ["tool", "serve", "worker", &format!("--port={bad}")];
691	        let (kind, msg) = fail_kind(&argv);
692	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
693	        assert!(msg.contains("--port"), "{argv:?}: {msg}");
694	        // The offending value is attributed verbatim, even when empty.
695	        assert!(msg.contains(&format!("'{bad}'")), "{argv:?}: {msg}");
696	    }
697	
698	    // Detached form: tokens that do not look like flags are consumed as the
699	    // value and rejected by the same parser, never loosely converted.
700	    for bad in [
701	        "", "+80", "0x10", "1_000", " 80", "80 ", "abc", "0", "65536",
702	    ] {
703	        let argv = ["tool", "serve", "worker", "--port", bad];
704	        let (kind, msg) = fail_kind(&argv);
705	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
706	        assert!(msg.contains("--port"), "{argv:?}: {msg}");
707	    }
708	
709	    // A detached negative number is consumed by the option lexer as a flag
710	    // and is therefore reported as the unknown token it actually is; it is
711	    // still rejected, never accepted or truncated.
712	    let (kind, msg) = fail_kind(&["tool", "serve", "worker", "--port", "-1"]);
713	    assert_eq!(kind, ErrorKind::UnknownArgument);
714	    assert!(msg.contains("-1"), "{msg}");
715	    assert!(msg.contains("tool serve worker"), "{msg}");
716	}
