use clap::Arg;
use clap::ArgAction;
use clap::Command;
use clap::error::ErrorKind;
use clap::value_parser;

fn tool() -> Command {
    Command::new("tool")
        .arg(
            Arg::new("config")
                .long("config")
                .global(true)
                .default_value("builtin.toml"),
        )
        .arg(
            Arg::new("define")
                .long("define")
                .action(ArgAction::Append)
                .value_parser(value_parser!(String)),
        )
        .allow_external_subcommands(true)
        .external_subcommand_value_parser(value_parser!(String))
        .subcommand(
            Command::new("serve")
                .alias("srv")
                .visible_alias("serve-http")
                .allow_external_subcommands(true)
                .external_subcommand_value_parser(value_parser!(String))
                .subcommand(
                    Command::new("worker")
                        .alias("wk")
                        .visible_alias("worker-http")
                        .arg(
                            Arg::new("port")
                                .long("port")
                                .required(true)
                                .value_parser(value_parser!(u16).range(1..))
                        )
                        .arg(Arg::new("trailing").num_args(1..).last(true)),
                ),
        )
        .subcommand(Command::new("check").alias("chk").arg(Arg::new("path")))
}

fn show(argv: &[&str]) {
    match tool().try_get_matches_from(argv) {
        Ok(m) => {
            let sub = m
                .subcommand()
                .map(|(n, s)| (n, s.subcommand().map(|(n2, s2)| (n2, s2.get_many::<String>("").map(|v| v.cloned().collect::<Vec<_>>())))));
            println!("OK   {argv:?}: {sub:?}");
        }
        Err(e) => println!(
            "ERR  {argv:?}: {:?}: {}",
            e.kind(),
            e.to_string().lines().next().unwrap_or("")
        ),
    }
}

fn main() {
    for argv in [
        &["tool", "srv", "wk", "--port", "80"][..],
        &["tool", "srv", "--", "wk", "x"][..],
        &["tool", "--", "srv", "x"][..],
        &["tool", "srv", "wk"][..],
        &["tool", "srv", "wk", "--port", "0"][..],
        &["tool", "srv", "--config", "c", "wk", "--port", "80"][..],
        &["tool", "srv", "chk"][..],
        &["tool", "chk", "path"][..],
        &["tool", "plug", "srv"][..],
        &["tool", "serve-http", "worker-http", "--port", "80"][..],
        &["tool", "srv", "wk", "--help"][..],
        &["tool", "sr", "x"][..],
    ] {
        show(argv);
    }
    let _ = ErrorKind::InvalidValue;
}
